'use strict';
const products = [
  {id:'mini',name:'AURA Mini',price:7900,finish:'Obsidian',use:'Everyday listening',design:'Sculpted cylinder',kicker:'SMALL FORM. BIG FEELING.',description:'A compact companion for the music, podcasts, and little rituals that make a day your own.',detail:'A sculpted cylindrical form with a recessed top and a finely finished silver rim. AURA Mini brings a considered presence to a bedside table, a quiet corner, or your everyday workspace.'},
  {id:'one',name:'AURA One',price:12900,finish:'Obsidian',use:'Your favourite room',design:'Rounded square',kicker:'YOUR SPACE. YOUR SOUND.',description:'Soft edges, a tactile finish, and an easy presence. A speaker that looks right wherever life happens.',detail:'Softly rounded edges meet a finely woven black grille. With a quiet, sculptural profile and simple top controls, AURA One feels naturally at home on a shelf, a desk, or a window ledge.'},
  {id:'studio',name:'AURA Studio',price:19900,finish:'Ivory',use:'Dedicated listening',design:'Ivory & brass',kicker:'A LITTLE MORE PRESENCE.',description:'Warm ivory, considered brass details, and a timeless silhouette. Give your favourite records a place of their own.',detail:'A wide, fabric-wrapped silhouette in warm ivory, finished with tactile brass controls and a slim metal base. AURA Studio is a centrepiece for the spaces where you settle in and really listen.'}
];
const currency = n => 'Rs. ' + n.toLocaleString('en-PK');
const findProduct = id => {const product=products.find(p=>p.id===id);if(!product)throw new Error('Unknown speaker. Choose mini, one, or studio.');return product;};
let slideIndex=0;
let activeProduct=products[0];
const bag=new Map();
const productDialog=document.getElementById('product-dialog');
const bagDialog=document.getElementById('bag-dialog');
let toastTimer;
function openDialog(dialog){document.querySelectorAll('dialog[open]').forEach(d=>d.close());dialog.showModal();document.body.classList.add('dialog-open');}
function closeDialog(dialog){dialog.close();document.body.classList.remove('dialog-open');}
function showProduct(id){const p=findProduct(id);activeProduct=p;document.getElementById('dialog-product-title').textContent=p.name;document.getElementById('dialog-price').textContent=currency(p.price);document.getElementById('dialog-description').textContent=p.detail;document.getElementById('dialog-finish').textContent=p.finish;document.getElementById('dialog-finish-dot').className='finish-dot '+(p.finish==='Ivory'?'ivory':'black');document.getElementById('dialog-use').textContent=p.use;document.getElementById('dialog-design').textContent=p.design;const image=document.getElementById('dialog-product-image');image.className='product-crop product-'+p.id;image.setAttribute('aria-label',p.name+' speaker in '+p.finish);openDialog(productDialog);return {product:p.name,price:p.price,currency:'PKR',status:'product_details_open'};}
function setSlide(index){if(!Number.isInteger(index)||index<0||index>=products.length)throw new Error('Speaker index must be 0, 1, or 2.');slideIndex=index;const p=products[index];document.querySelectorAll('[data-slide]').forEach(b=>{const active=Number(b.dataset.slide)===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.getElementById('feature-product-image').className='product-crop product-'+p.id;document.getElementById('feature-product-image').setAttribute('aria-label',p.name+' speaker');document.getElementById('feature-title').textContent=p.name;document.getElementById('feature-number').textContent='0'+(index+1)+' / 03';document.getElementById('feature-kicker').textContent=p.kicker;document.getElementById('feature-copy').textContent=p.description;document.getElementById('feature-explore').dataset.product=p.id;document.getElementById('feature-explore').innerHTML='Explore '+p.name.replace('AURA ','')+' <span aria-hidden="true">+</span>';document.getElementById('slide-current').textContent='0'+(index+1);document.getElementById('slider-progress-fill').style.transform='translateX('+index*100+'%)';const detail=document.getElementById('feature-detail-image');detail.style.backgroundImage='url('+(index===0?'assets/hero.png':'assets/lifestyle.png')+')';detail.setAttribute('aria-label',index===0?'Close-up of the AURA Mini’s sculpted rim':p.name+' in a naturally lit interior');detail.style.backgroundPosition=index===0?'55% 20%':index===1?'75% 35%':'25% 70%';return {selected:p.id};}
function toast(message){const el=document.getElementById('toast');clearTimeout(toastTimer);el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},3000);}
function updateBadge(){const count=[...bag.values()].reduce((a,b)=>a+b,0);const badge=document.querySelector('.bag-count');badge.textContent=String(count);badge.hidden=count===0;document.querySelector('[data-open-bag]').setAttribute('aria-label','Open shopping bag'+(count?', '+count+' item'+(count===1?'':'s'):''));}
function renderBag(){const container=document.getElementById('bag-items');const summary=document.getElementById('bag-summary');container.replaceChildren();if(!bag.size){container.innerHTML='<div class="bag-empty"><h3>A little space for good sound.</h3><p>Your bag is empty.<br>Find the speaker that feels like you.</p><button type="button" class="button button-black" id="empty-explore">Explore speakers</button></div>';container.querySelector('button').addEventListener('click',()=>{closeDialog(bagDialog);document.getElementById('collection').scrollIntoView({behavior:'auto'});});summary.hidden=true;return;}summary.hidden=false;let total=0;for(const [id,quantity] of bag){const p=findProduct(id);total+=p.price*quantity;const row=document.createElement('div');row.className='bag-row';row.innerHTML='<div class="bag-product-image"><span class="product-crop product-'+p.id+'" role="img" aria-label="'+p.name+'"></span></div><div class="bag-product-info"><h3>'+p.name+'</h3><p>'+currency(p.price)+' · '+p.finish+'</p><div class="quantity-controls"><button type="button" data-bag-action="minus" data-id="'+p.id+'" aria-label="Decrease '+p.name+' quantity">−</button><span aria-label="Quantity">'+quantity+'</span><button type="button" data-bag-action="plus" data-id="'+p.id+'" aria-label="Increase '+p.name+' quantity" '+(quantity>=9?'disabled':'')+'>+</button><button type="button" class="remove-item" data-bag-action="remove" data-id="'+p.id+'" aria-label="Remove '+p.name+'">Remove</button></div></div>';container.append(row);}document.getElementById('bag-total').textContent=currency(total);}
function addToBag(id,quantity=1){const p=findProduct(id);if(!Number.isInteger(quantity)||quantity<1||quantity>9)throw new Error('Quantity must be an integer from 1 to 9.');const next=(bag.get(id)||0)+quantity;if(next>9)throw new Error('A maximum of 9 of each speaker can be selected.');bag.set(id,next);updateBadge();renderBag();toast(p.name+' added to your bag');return {product:id,quantity:next,cartCount:[...bag.values()].reduce((a,b)=>a+b,0),orderPlaced:false};}
document.addEventListener('click',event=>{const productButton=event.target.closest('[data-product]');if(productButton){showProduct(productButton.dataset.product);return;}if(event.target.closest('[data-open-bag]')){renderBag();openDialog(bagDialog);return;}const closeButton=event.target.closest('[data-close-dialog]');if(closeButton){closeDialog(closeButton.closest('dialog'));return;}const category=event.target.closest('[data-slide]');if(category){setSlide(Number(category.dataset.slide));return;}const bagAction=event.target.closest('[data-bag-action]');if(bagAction){const {id,bagAction:action}=bagAction.dataset;const old=bag.get(id)||0;if(action==='remove'||(action==='minus'&&old===1))bag.delete(id);else bag.set(id,Math.max(1,Math.min(9,old+(action==='plus'?1:-1))));renderBag();updateBadge();}});
document.getElementById('add-to-bag').addEventListener('click',()=>{try{addToBag(activeProduct.id);closeDialog(productDialog);renderBag();openDialog(bagDialog);}catch(error){toast(error.message);}});
document.getElementById('continue-browsing').addEventListener('click',()=>closeDialog(bagDialog));
document.getElementById('previous-slide').addEventListener('click',()=>setSlide((slideIndex+2)%3));
document.getElementById('next-slide').addEventListener('click',()=>setSlide((slideIndex+1)%3));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('dialog-open');});dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog);}});});
const menuButton=document.querySelector('.mobile-menu');const mobileNav=document.getElementById('mobile-nav');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));menuButton.setAttribute('aria-label',open?'Open navigation':'Close navigation');mobileNav.hidden=open;});
mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileNav.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open navigation');}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!mobileNav.hidden){mobileNav.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.focus();}});
document.getElementById('story-toggle').addEventListener('click',event=>{const button=event.currentTarget;const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));document.getElementById('story-more').hidden=expanded;button.textContent=expanded?'Our philosophy':'Read less';});
document.getElementById('year').textContent=new Date().getFullYear();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'aura_read_collection',title:'Read the AURA speaker collection',description:'Read the three AURA concept speakers and the current in-page bag. No order is placed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {products:products.map(({id,name,price,finish,description})=>({id,name,price,currency:'PKR',finish,description})),bag:[...bag].map(([id,quantity])=>({id,quantity})),orderingAvailable:false};}});register({name:'aura_open_speaker',title:'View an AURA speaker',description:'Open a speaker’s detail dialog. This does not add it to the bag or place an order.',inputSchema:{type:'object',properties:{productId:{type:'string',enum:['mini','one','studio']}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.productId!=='string')throw new Error('productId is required.');return showProduct(input.productId);}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
